const MAP = new Map();
for (let i = 0; i < PAIRS.length; i += 2)
    MAP.set(PAIRS[i], PAIRS[i + 1]);
/** 繁体 → 简体（逐字查表；表里没有的字原样保留） */
export function toHans(text) {
    if (!text)
        return text;
    let out = '';
    let changed = false;
    for (const ch of text) {
        const s = MAP.get(ch);
        if (s && s !== ch) {
            out += s;
            changed = true;
        }
        else {
            out += ch;
        }
    }
    return changed ? out : text;
}
/** 这个字有没有在表里（测试与调试用） */
export const hasHansPair = (trad) => MAP.has(trad);
